// vite.config.ts
import { defineConfig } from 'vite';
import { wgpuKitHotReload } from 'wgpu-kit/vite';
export default defineConfig({ plugins: [wgpuKitHotReload()] });

import { elementKernel } from 'wgpu-kit';
import { hotKernel } from 'wgpu-kit/vite';
import code from './sim.wgsl?raw';
const kernel = elementKernel({ state: { pos: 'vec2f' }, code });
hotKernel(kernel, import.meta.hot, './sim.wgsl');
